+func normalizeLaunchError(err error) error {
+	const prefix = "Unrecognized remote plugin message: "
+
+	msg := err.Error()
+	if !strings.HasPrefix(msg, prefix) {
+		return err
+	}
+
+	remoteMsg, _, _ := strings.Cut(strings.TrimPrefix(msg, prefix), "\nThis usually means")
+	return fmt.Errorf("Unrecognized remote plugin message: %s\n\nThis usually means that the plugin is either invalid or simply\nneeds to be recompiled to support the latest protocol.", remoteMsg)
+}

